import { ObjectId } from "mongodb";
import { NextRequest } from "next/server";

import { fail, ok } from "@/lib/api-response";
import { requireSession } from "@/lib/auth-guard";
import { usersCol } from "@/lib/collections";
import { deleteFile, uploadImage } from "@/lib/cloudinary";
import { ensureIndexes } from "@/lib/indexes";

const allowedTypes = ["image/jpeg", "image/png", "image/webp"];
const maxSize = 5 * 1024 * 1024;

export async function POST(req: NextRequest) {
  const session = await requireSession();

  if (!session) {
    return fail("Not authenticated", 401);
  }

  let formData: FormData;

  try {
    formData = await req.formData();
  } catch {
    return fail("Invalid upload", 400);
  }
  const file = formData.get("file");

  if (!(file instanceof File)) {
    return fail("File is required", 400);
  }

  if (!allowedTypes.includes(file.type)) {
    return fail("Unsupported image format", 400);
  }

  if (file.size === 0 || file.size > maxSize) {
    return fail("Image must be under 5 MB", 400);
  }

  try {
    await ensureIndexes();

    const userCollection = await usersCol();
    const user = await userCollection.findOne({
      _id: new ObjectId(session.userId),
    });

    if (!user) {
      return fail("User not found", 404);
    }

    const buffer = Buffer.from(await file.arrayBuffer());
    const upload = await uploadImage(
      buffer,
      `bjs-prep/avatars/${session.userId}`,
      file.type,
    );

    await userCollection.updateOne(
      { _id: user._id },
      {
        $set: {
          avatarUrl: upload.secureUrl,
          avatarPublicId: upload.publicId,
          updatedAt: new Date(),
        },
      },
    );

    if (user.avatarPublicId) {
      try {
        await deleteFile(user.avatarPublicId, "image");
      } catch {
        // Ignore Cloudinary cleanup errors.
      }
    }

    return ok({ avatarUrl: upload.secureUrl });
  } catch (error) {
    console.error("Avatar upload error", error);
    return fail("Server error", 500);
  }
}

export async function DELETE() {
  const session = await requireSession();

  if (!session) {
    return fail("Not authenticated", 401);
  }

  try {
    await ensureIndexes();

    const userCollection = await usersCol();
    const user = await userCollection.findOne({
      _id: new ObjectId(session.userId),
    });

    if (!user) {
      return fail("User not found", 404);
    }

    if (user.avatarPublicId) {
      try {
        await deleteFile(user.avatarPublicId, "image");
      } catch {
        // Ignore Cloudinary cleanup errors.
      }
    }

    await userCollection.updateOne(
      { _id: user._id },
      {
        $unset: {
          avatarUrl: "",
          avatarPublicId: "",
        },
        $set: { updatedAt: new Date() },
      },
    );

    return ok({ message: "Avatar removed." });
  } catch (error) {
    console.error("Avatar removal error", error);
    return fail("Server error", 500);
  }
}
