import { Db, MongoClient } from "mongodb";
import * as fs from "node:fs";
import * as path from "node:path";

function getEnvValue(name: string): string | undefined {
  const existing = process.env[name];

  if (existing?.trim()) {
    return existing.trim();
  }

  const envPath = path.resolve(process.cwd(), ".env.local");

  if (!fs.existsSync(envPath)) {
    return undefined;
  }

  for (const line of fs.readFileSync(envPath, "utf8").split(/\r?\n/)) {
    const trimmed = line.trim();

    if (!trimmed || trimmed.startsWith("#")) {
      continue;
    }

    const equalsIndex = trimmed.indexOf("=");

    if (equalsIndex === -1) {
      continue;
    }

    const key = trimmed.slice(0, equalsIndex).trim();

    const value = trimmed
      .slice(equalsIndex + 1)
      .trim()
      .replace(/^['"]|['"]$/g, "");

    if (key === name) {
      return value;
    }
  }

  return undefined;
}

type Cached = {
  client: MongoClient | null;
  db: Db | null;
  promise: Promise<Db> | null;
};

const globalWithMongo = globalThis as typeof globalThis & {
  __bjsMongo?: Cached;
};

const cached: Cached =
  globalWithMongo.__bjsMongo ?? {
    client: null,
    db: null,
    promise: null,
  };

if (!globalWithMongo.__bjsMongo) {
  globalWithMongo.__bjsMongo = cached;
}

export async function getDb(): Promise<Db> {
  if (cached.db) {
    return cached.db;
  }

  if (!cached.promise) {
    const uri = getEnvValue("MONGODB_URI");

    if (!uri) {
      throw new Error("MONGODB_URI is not set.");
    }

    console.log("MongoDB URI detected:", uri.replace(
      /\/\/([^:]+):([^@]+)@/,
      "//$1:****@"
    ));

    const client = new MongoClient(uri, {
      serverSelectionTimeoutMS: 10000,
      connectTimeoutMS: 10000,
    });

    cached.promise = client
      .connect()
      .then((connectedClient) => {
        cached.client = connectedClient;
        cached.db = connectedClient.db("bjs-prep");

        console.log("MongoDB connected successfully.");

        return cached.db;
      })
      .catch((error) => {
        cached.promise = null;
        console.error("MongoDB connection failed:", error);
        throw error;
      });
  }

  return cached.promise;
}